.tree {
  min-width: 0;
  container: agent-tree / inline-size;
}
.group {
  list-style: none;
  margin: 0;
  padding: 0;
}
.node {
  outline: none;
  min-width: 0;
}
.row {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  padding: 0 8px 0 calc(8px + var(--depth) * var(--tree-indent));
  border-radius: 4px;
  cursor: pointer;
  transition: background var(--motion-hover) ease-out;
}
.row:not([data-disabled="true"]):hover {
  background: var(--surface-hover);
}
.row:not([data-disabled="true"]):active {
  background: var(--surface-pressed);
}
.node[data-selected="true"] > .row {
  background: var(--selection);
}
.node[data-selected="true"] > .row::before {
  content: "";
  position: absolute;
  left: 0;
  top: 4px;
  bottom: 4px;
  width: 2px;
  background: var(--primary);
}
.node:focus-visible > .row {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
}
.row[data-disabled="true"] {
  cursor: default;
  opacity: 0.45;
}
.node[data-dragging="true"] > .row {
  opacity: 0.45;
}
.row[data-drop="inside"] {
  background: var(--selection);
  box-shadow: inset 0 0 0 1px var(--info);
}
.row[data-drop="before"] {
  box-shadow: inset 0 2px var(--info);
}
.row[data-drop="after"] {
  box-shadow: inset 0 -2px var(--info);
}
.chevron {
  display: grid;
  place-items: center;
  flex: 0 0 28px;
  height: 28px;
  margin-right: -4px;
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  border-radius: 4px;
}
.chevron svg[data-open="true"] {
  transform: rotate(90deg);
}
.chevron:disabled {
  cursor: default;
}
.leaf {
  flex: 0 0 28px;
  margin-right: -4px;
}
.icon {
  display: grid;
  place-items: center;
  flex: 0 0 16px;
  height: 16px;
}
.icon svg {
  width: 16px;
  height: 16px;
  stroke-width: 1.75;
}
.title {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 13px;
  line-height: 20px;
}
.metadata {
  max-width: 96px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  color: var(--text-secondary);
}
.status {
  flex-shrink: 0;
  max-width: 88px;
  overflow: hidden;
}
.grip {
  flex-shrink: 0;
  color: var(--text-muted);
  cursor: grab;
}
.move {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding: 12px 8px;
  margin-top: 12px;
  border-top: 1px solid var(--border);
  font-size: 12px;
  line-height: 20px;
}
.move > span {
  flex-basis: 100%;
  overflow-wrap: anywhere;
  color: var(--text-secondary);
}
.move select {
  height: 32px;
  max-width: 100%;
  min-width: 0;
  padding: 0 8px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--surface);
  color: inherit;
}
.move select:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
.announcement {
  font-size: 12px;
  line-height: 20px;
  color: var(--text-secondary);
}
.announcement:empty {
  display: none;
}
@container agent-tree (max-width: 400px) {
  .metadata {
    display: none;
  }
  .grip {
    display: none;
  }
}
@media (pointer: coarse) {
  .row {
    min-height: 44px;
  }
  .chevron {
    flex-basis: 44px;
    height: 44px;
  }
  .leaf {
    flex-basis: 44px;
  }
  .move select {
    min-height: 44px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .row {
    transition: none;
  }
}
